import { isJsonObject } from '../saved-format.ts';
import { decodeExchange } from './decode.ts';
import type { Tournament } from './tournament.ts';
const key = 'np3:tournaments';
export function readHistory(): { items: Tournament[]; failed: boolean } {
  try {
    const text = localStorage.getItem(key);
    if (!text) return { items: [], failed: false };
    const value: unknown = JSON.parse(text);
    if (!isJsonObject(value) || Object.keys(value).length !== 2 || value.v !== 3 || !Array.isArray(value.items) || value.items.length > 10) return { items: [], failed: false };
    const items: Tournament[] = [];
    for (const item of value.items) {
      const result = decodeExchange(JSON.stringify({ format: 'neon-pairs/tournament', version: 1, tournament: item, snapshot: null }));
      if (!result.value?.tournament || result.value.tournament.phase !== 'complete') return { items: [], failed: false };
      items.push(result.value.tournament);
    }
    return { items, failed: false };
  } catch (error) { return { items: [], failed: !(error instanceof SyntaxError) }; }
}
export function writeHistory(items: Tournament[]): boolean {
  try { localStorage.setItem(key, JSON.stringify({ v: 3, items })); return true; } catch { return false; }
}
